import os
from pathlib import Path

root = Path(os.environ['ANDROID_DIR']) / 'app/src/main/assets/www'
index = root / 'index.html'
if not index.exists():
    raise SystemExit('index.html nao encontrado')

css = r'''
#msRpg26{position:fixed;inset:0;z-index:2147483000;background:#07111f;color:#f7fafc;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;overflow:auto;padding-bottom:max(28px,env(safe-area-inset-bottom));}
#msRpg26 *{box-sizing:border-box} #msRpg26 button{font:inherit;color:inherit}
.r26-head{position:sticky;top:0;z-index:20;background:linear-gradient(180deg,#07111f 82%,#07111f00);padding:18px 18px 10px;display:flex;align-items:center;gap:12px}
.r26-title{font-size:26px;font-weight:900;letter-spacing:-.04em}.r26-badge{font-size:12px;font-weight:900;padding:7px 10px;border-radius:999px;background:#22e6a8;color:#042419}.r26-spacer{flex:1}.r26-circle{width:44px;height:44px;border-radius:14px;border:1px solid #26384f;background:#0d1a2b;display:grid;place-items:center;font-size:22px;font-weight:900}
.r26-tabs{display:flex;gap:9px;overflow:auto;padding:8px 18px 14px;scrollbar-width:none;border-bottom:1px solid #17263a}.r26-tabs::-webkit-scrollbar{display:none}.r26-tab{white-space:nowrap;border:1px solid #273952;background:#0b1727;color:#aebbd0;padding:11px 16px;border-radius:15px;font-weight:800}.r26-tab.on{background:linear-gradient(135deg,#0fa57d,#21dcaa);color:#fff;border-color:#32ecc0;box-shadow:0 8px 25px #0cba8a33}
.r26-wrap{padding:18px;max-width:760px;margin:auto}.r26-panel{display:none}.r26-panel.on{display:block}.r26-card{background:linear-gradient(180deg,#0d1a2a,#0a1523);border:1px solid #20334a;border-radius:24px;box-shadow:0 18px 50px #0005}
.r26-hero{padding:16px;overflow:hidden;position:relative}.r26-hero:before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 35%,#1c8cff22,transparent 45%),radial-gradient(circle at 50% 100%,#18e3a622,transparent 44%);pointer-events:none}.r26-avatar{height:390px;display:grid;place-items:center;position:relative}.r26-avatar svg{width:min(300px,85vw);height:370px;filter:drop-shadow(0 18px 20px #0009)}
.r26-ring{position:absolute;bottom:20px;width:230px;height:56px;border-radius:50%;border:3px solid #1ee6b466;box-shadow:0 0 28px #16d9aa55 inset,0 0 30px #16d9aa33}.r26-levelrow{display:flex;align-items:flex-end;gap:14px;padding:0 10px 10px}.r26-level{font-size:52px;font-weight:950;line-height:.9}.r26-muted{color:#9cadc3}.r26-xp{height:11px;background:#17263a;border-radius:999px;overflow:hidden;margin-top:10px}.r26-xp i{display:block;height:100%;width:38%;background:linear-gradient(90deg,#1de6b0,#24b98c)}.r26-boost{margin-left:auto;border:1px solid #1c8d6e;background:#082b25;padding:12px 15px;border-radius:18px;text-align:center;font-weight:800}.r26-boost b{display:block;color:#28efb5;font-size:27px}
.r26-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.r26-stat{padding:16px;text-align:center}.r26-stat small{display:block;color:#91a1b8;text-transform:uppercase}.r26-stat b{font-size:32px}
.r26-section-title{font-size:24px;font-weight:900;margin:2px 2px 4px}.r26-sub{color:#9cabc0;margin:0 2px 16px;line-height:1.45}.r26-filter{display:flex;gap:8px;overflow:auto;margin-bottom:14px;scrollbar-width:none}.r26-filter button{border:1px solid #273952;background:#0b1727;padding:9px 12px;border-radius:13px;font-weight:800;white-space:nowrap;color:#adbbcf}.r26-filter button.on{background:#0c876b;border-color:#29e4b4;color:white}
.r26-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.r26-item{position:relative;overflow:hidden;border:1px solid #263a53;border-radius:20px;background:#0c1828;padding:11px;min-height:205px}.r26-item.epic{border-color:#a64de5aa}.r26-item.legendary{border-color:#e8b83d}.r26-art{height:105px;border-radius:14px;background:radial-gradient(circle at 50% 45%,#263c57,#0a1320);display:grid;place-items:center;margin-bottom:10px;overflow:hidden}.r26-art svg{width:88px;height:88px;filter:drop-shadow(0 8px 10px #0008)}.r26-item h3{font-size:14px;margin:0 0 6px;line-height:1.25}.r26-rarity{font-size:10px;font-weight:900;padding:4px 7px;border-radius:999px;display:inline-block;margin-bottom:6px}.epic .r26-rarity{background:#7c2bb7;color:#f0d5ff}.legendary .r26-rarity{background:#5b430b;color:#ffd86e}.rare .r26-rarity{background:#123d75;color:#85c6ff}.r26-bonus{font-size:11px;color:#9fb0c6;min-height:29px}.r26-equip{width:100%;margin-top:9px;border:1px solid #2d435d;background:#14243a;padding:9px;border-radius:12px;font-weight:900}.r26-equip.on{background:#0c8d6e;border-color:#24d9aa}.r26-equipped{position:absolute;top:8px;right:8px;background:#1fe1ac;color:#05271f;font-size:9px;font-weight:950;padding:4px 6px;border-radius:8px}
.r26-list{display:grid;gap:12px}.r26-row{padding:16px;display:flex;gap:14px;align-items:center}.r26-icon{width:46px;height:46px;border-radius:14px;background:#12243a;border:1px solid #29415d;display:grid;place-items:center;font-weight:950;color:#35e8b8}.r26-row .grow{flex:1}.r26-row h3{margin:0 0 4px;font-size:16px}.r26-progress{height:8px;background:#17263a;border-radius:99px;overflow:hidden;margin-top:8px}.r26-progress i{display:block;height:100%;background:#21dca9;border-radius:99px}.r26-reward{font-size:12px;font-weight:900;color:#f4c95d}
.r26-pass{display:grid;gap:12px}.r26-passrow{display:grid;grid-template-columns:54px 1fr auto;gap:12px;align-items:center;padding:14px}.r26-tier{width:48px;height:48px;border-radius:15px;background:#101f31;border:1px solid #2a415d;display:grid;place-items:center;font-weight:950;font-size:18px}.r26-claim{border:1px solid #2b4059;background:#132238;padding:9px 11px;border-radius:12px;font-weight:900}.r26-claim.ready{background:#11856a;border-color:#2bdcb0}
.r26-rank{display:grid;gap:9px}.r26-rankrow{display:grid;grid-template-columns:38px 44px 1fr auto;align-items:center;gap:10px;padding:12px 14px}.r26-place{font-weight:950;text-align:center}.r26-mini{width:42px;height:42px;border-radius:14px;background:linear-gradient(145deg,#1a314f,#0d1928);display:grid;place-items:center;font-weight:950}.r26-power{font-weight:950;color:#53e6bc}.r26-footnote{text-align:center;color:#6f819a;font-size:12px;padding:20px 0 6px}
@media(min-width:580px){.r26-grid{grid-template-columns:repeat(3,1fr)}}
'''

js = r'''(()=>{'use strict';
const ITEMS=[
{id:'crown',name:'Coroa do Campeão',slot:'head',rar:'legendary',xp:25,power:28,color:'#f4c84b'},
{id:'archhat',name:'Chapéu do Arquimago',slot:'head',rar:'epic',xp:10,power:12,color:'#9d54e8'},
{id:'armor',name:'Armadura do Artilheiro',slot:'armor',rar:'legendary',xp:20,power:35,color:'#e5b840'},
{id:'bluearmor',name:'Peitoral Azul',slot:'armor',rar:'rare',xp:5,power:14,color:'#2c8ff0'},
{id:'cape',name:'Manto da Vitória',slot:'cape',rar:'epic',xp:12,power:15,color:'#8b47d1'},
{id:'boots',name:'Chuteiras Relâmpago',slot:'boots',rar:'epic',xp:10,power:18,color:'#19bca0'},
{id:'sword',name:'Lâmina do Capitão',slot:'weapon',rar:'legendary',xp:20,power:42,color:'#e9c453'},
{id:'aura',name:'Aura da Torcida',slot:'aura',rar:'epic',xp:15,power:10,color:'#28d9c3'}];
const SLOT={head:'Cabeça',armor:'Corpo',cape:'Manto',weapon:'Relíquias',boots:'Chuteiras',aura:'Aura'};
const K='ms_rpg26_state';let st={eq:{head:'archhat',armor:null,cape:null,weapon:null,boots:null,aura:null},level:1,xp:38,coins:520};try{st={...st,...JSON.parse(localStorage.getItem(K)||'{}')}}catch(e){};
function save(){localStorage.setItem(K,JSON.stringify(st))}
function itemArt(it){let s=''; if(it.slot==='head')s=`<path d="M18 58 Q45 10 72 58 L64 73 H27Z" fill="${it.color}" stroke="#f8df87" stroke-width="4"/><circle cx="45" cy="47" r="8" fill="#d7b4ff"/>`;if(it.slot==='armor')s=`<path d="M22 24 L35 15 45 24 55 15 69 24 64 76H27Z" fill="${it.color}" stroke="#f6d66f" stroke-width="4"/><path d="M36 36h18v24H36z" fill="#13263b"/>`;if(it.slot==='cape')s=`<path d="M27 13 Q49 21 68 14 L75 76 Q45 65 18 77Z" fill="${it.color}" stroke="#d0b6ff" stroke-width="4"/><path d="M30 27q18 8 35 0" fill="none" stroke="#fff8" stroke-width="4"/>`;if(it.slot==='boots')s=`<path d="M19 22h23v41l-7 13H13l7-20zM52 22h23l-1 54H50l4-16z" fill="${it.color}" stroke="#ffe88e" stroke-width="4"/>`;if(it.slot==='weapon')s=`<path d="M22 72L66 17" stroke="#c8f2ff" stroke-width="9"/><path d="M22 72L66 17" stroke="${it.color}" stroke-width="4"/><path d="M18 60l17 14" stroke="#f2c84b" stroke-width="7"/><circle cx="21" cy="74" r="7" fill="#f2c84b"/>`;if(it.slot==='aura')s=`<ellipse cx="45" cy="50" rx="31" ry="18" fill="none" stroke="${it.color}" stroke-width="6"/><ellipse cx="45" cy="50" rx="21" ry="10" fill="none" stroke="#b9fff1" stroke-width="3"/>`;return `<svg viewBox="0 0 90 90">${s}</svg>`}
function avatar(){const E=st.eq;return `<div class="r26-avatar"><div class="r26-ring"></div><svg viewBox="0 0 240 370" aria-label="Jogador RPG"><defs><linearGradient id="jer26" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#f8fbff"/><stop offset="1" stop-color="#cbd6e5"/></linearGradient></defs>${E.aura?'<ellipse cx="120" cy="326" rx="82" ry="23" fill="none" stroke="#32e6c2" stroke-width="6" opacity=".8"/>':''}${E.cape?'<path d="M149 137Q191 165 178 289L135 255Z" fill="#6840b2" stroke="#b79cff" stroke-width="5"/>':''}<g><circle cx="120" cy="83" r="38" fill="#d88c5f"/><path d="M82 80q6-48 38-47 31 3 39 45l-18-20-11 12-15-13-15 16z" fill="#45271d"/><path d="M101 89h13M130 89h13" stroke="#1b1a1a" stroke-width="5"/><path d="M108 108q12 8 24 0" stroke="#5e2d23" stroke-width="5" fill="none"/></g><g>${E.armor?'<path d="M82 130l25-13 13 13 14-13 25 13-8 103H88Z" fill="#1559b7" stroke="#e8bd4b" stroke-width="6"/><path d="M105 148h30l-5 43h-20z" fill="#e8bd4b"/>':'<path d="M86 130h68q10 0 10 12v91H78v-91q0-12 8-12z" fill="url(#jer26)" stroke="#aebed0" stroke-width="4"/><path d="M78 132h86v17H78z" fill="#14263b"/><rect x="110" y="158" width="21" height="23" rx="4" fill="#14263b"/>'}<path d="M78 145l-27 25 10 57 27-13z" fill="#d88c5f"/><path d="M164 145l27 25-10 57-27-13z" fill="#d88c5f"/><path d="M86 230h35l-5 67H78zM121 230h35l9 67h-43z" fill="#152236"/>${E.boots?'<path d="M76 281h42l-5 58H67zM125 281h42l9 58h-48z" fill="#d8aa2f" stroke="#ffe581" stroke-width="5"/>':'<path d="M78 293h38l-3 47H69zM126 293h39l10 47h-48z" fill="#f1f4f8" stroke="#17263a" stroke-width="5"/>'}</g>${E.head?'<path d="M79 75q14-55 41-55 30 2 43 55l-22-15-11 13-14-14-15 14z" fill="#7340b3" stroke="#e5c86a" stroke-width="5"/>':''}${E.weapon?'<g><path d="M58 211L25 307" stroke="#bfeeff" stroke-width="11"/><path d="M58 211L25 307" stroke="#2daeff" stroke-width="5"/><path d="M47 235l25 9" stroke="#edc552" stroke-width="8"/></g>':''}</svg></div>`}
function itemCard(it){let on=st.eq[it.slot]===it.id;return `<div class="r26-item ${it.rar}" data-slot="${it.slot}"><div class="r26-art">${itemArt(it)}</div>${on?'<span class="r26-equipped">EQUIPADO</span>':''}<h3>${it.name}</h3><span class="r26-rarity">${it.rar==='legendary'?'LENDÁRIO':it.rar==='epic'?'ÉPICO':'RARO'}</span><div class="r26-bonus">+${it.xp}% XP · +${it.power} poder</div><button class="r26-equip ${on?'on':''}" data-equip="${it.id}">${on?'Remover':'Equipar'}</button></div>`}
function renderInv(filter='all'){let arr=filter==='all'?ITEMS:ITEMS.filter(x=>x.slot===filter);return `<div class="r26-section-title">Inventário RPG</div><p class="r26-sub">Equipamentos compactos, legíveis e aplicados diretamente ao personagem.</p><div class="r26-filter"><button class="on" data-filter="all">Todos</button>${Object.entries(SLOT).map(([k,v])=>`<button data-filter="${k}">${v}</button>`).join('')}</div><div class="r26-grid">${arr.map(itemCard).join('')}</div>`}
function challenges(){return `<div class="r26-section-title">Desafios diários</div><p class="r26-sub">Complete objetivos para ganhar XP, coins e progresso no passe.</p><div class="r26-list">${[['Palpite certeiro','Acerte 1 resultado hoje',65,120],['Sequência do dia','Faça 3 palpites',33,80],['Olho de técnico','Abra 2 escalações',50,70],['Mestre da rodada','Acerte 3 palpites',10,250]].map((x,i)=>`<div class="r26-card r26-row"><div class="r26-icon">${i+1}</div><div class="grow"><h3>${x[0]}</h3><div class="r26-muted">${x[1]}</div><div class="r26-progress"><i style="width:${x[2]}%"></i></div></div><div class="r26-reward">+${x[3]} XP</div></div>`).join('')}</div>`}
function pass(){return `<div class="r26-section-title">Passe da temporada</div><p class="r26-sub">100% gratuito. Recompensas melhores nos marcos mais altos.</p><div class="r26-pass">${[['1','150 Coins',1],['5','Baú Raro',1],['10','Manto do Estádio',0],['20','Boost +15% XP',0],['35','Chuteiras Épicas',0],['50','Armadura Lendária',0]].map(x=>`<div class="r26-card r26-passrow"><div class="r26-tier">${x[0]}</div><div><b>${x[1]}</b><div class="r26-muted">Marco ${x[0]}</div></div><button class="r26-claim ${x[2]?'ready':''}">${x[2]?'Resgatar':'Bloqueado'}</button></div>`).join('')}</div>`}
function rank(){let names=['RafaGoal','ViniScout','MagoDaBola','TaticoBR','GoleadorX','Samonte','ArenaMaster','NinjaFC','Craque10','FutStats'];return `<div class="r26-section-title">Ranking de força</div><p class="r26-sub">Temporada mensal · Top 200 jogadores.</p><div class="r26-rank">${names.map((n,i)=>`<div class="r26-card r26-rankrow"><div class="r26-place">${i+1}</div><div class="r26-mini">${n[0]}</div><div><b>${n}</b><div class="r26-muted">Nível ${Math.max(1,74-i*5)}</div></div><div class="r26-power">${1320-i*73}</div></div>`).join('')}</div><div class="r26-footnote">Mostrando Top 10 de 200</div>`}
function player(){let p=10+ITEMS.filter(i=>st.eq[i.slot]===i.id).reduce((a,b)=>a+b.power,0);return `<div class="r26-card r26-hero">${avatar()}<div class="r26-levelrow"><div><div class="r26-muted">Nível</div><div class="r26-level">${st.level}</div><div class="r26-muted" style="margin-top:8px">${st.xp}% do nível</div><div class="r26-xp"><i style="width:${st.xp}%"></i></div></div><div class="r26-boost">Boost ativo<b>+35% XP</b></div></div></div><div class="r26-stats"><div class="r26-card r26-stat"><small>Força</small><b>${p}</b></div><div class="r26-card r26-stat"><small>Defesa</small><b>${14+(st.eq.armor?35:0)}</b></div><div class="r26-card r26-stat"><small>Velocidade</small><b>${18+(st.eq.boots?18:0)}</b></div><div class="r26-card r26-stat"><small>Magia</small><b>${21+(st.eq.head?12:0)}</b></div></div>`}
function shell(){return `<div id="msRpg26"><div class="r26-head"><div class="r26-title">Meu jogador</div><div class="r26-badge">BETA 26</div><div class="r26-spacer"></div><button class="r26-circle" data-close>×</button></div><div class="r26-tabs">${[['player','Jogador'],['inv','Inventário'],['ch','Desafios'],['pass','Passe'],['rank','Ranking']].map((x,i)=>`<button class="r26-tab ${i?'':'on'}" data-tab="${x[0]}">${x[1]}</button>`).join('')}</div><div class="r26-wrap"><section class="r26-panel on" data-panel="player">${player()}</section><section class="r26-panel" data-panel="inv">${renderInv()}</section><section class="r26-panel" data-panel="ch">${challenges()}</section><section class="r26-panel" data-panel="pass">${pass()}</section><section class="r26-panel" data-panel="rank">${rank()}</section></div></div>`}
function refreshPlayer(){let p=document.querySelector('[data-panel="player"]');if(p)p.innerHTML=player()}
function refreshInv(f='all'){let p=document.querySelector('[data-panel="inv"]');if(p)p.innerHTML=renderInv(f)}
function bind(){document.addEventListener('click',e=>{let t=e.target.closest('#msRpg26 [data-tab]');if(t){document.querySelectorAll('#msRpg26 .r26-tab').forEach(x=>x.classList.toggle('on',x===t));document.querySelectorAll('#msRpg26 .r26-panel').forEach(x=>x.classList.toggle('on',x.dataset.panel===t.dataset.tab));return}let f=e.target.closest('#msRpg26 [data-filter]');if(f){refreshInv(f.dataset.filter);document.querySelectorAll('#msRpg26 [data-filter]').forEach(x=>x.classList.toggle('on',x.dataset.filter===f.dataset.filter));return}let b=e.target.closest('#msRpg26 [data-equip]');if(b){let it=ITEMS.find(x=>x.id===b.dataset.equip);if(!it)return;st.eq[it.slot]=st.eq[it.slot]===it.id?null:it.id;save();refreshPlayer();refreshInv('all');return}if(e.target.closest('#msRpg26 [data-close]')){document.getElementById('msRpg26')?.remove();history.back();}},true)}
function shouldMount(){let txt=document.body?.innerText||'';return /Meu jogador/i.test(txt)&&(/Inventário|Desafios|Passe|Ranking/i.test(txt))}
function mount(){if(document.getElementById('msRpg26')||!shouldMount())return;document.body.insertAdjacentHTML('beforeend',shell())}
function boot(){bind();mount();new MutationObserver(()=>mount()).observe(document.body,{childList:true,subtree:true})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();'''

(root/'beta-v26.css').write_text(css,encoding='utf-8')
(root/'beta-v26.js').write_text(js,encoding='utf-8')
h=index.read_text(encoding='utf-8')
if 'beta-v26.css' not in h:h=h.replace('</head>','<link rel="stylesheet" href="beta-v26.css?v=26"></head>')
if 'beta-v26.js' not in h:h=h.replace('</body>','<script src="beta-v26.js?v=26"></script></body>')
index.write_text(h,encoding='utf-8')
print('Beta 26 RPG rebuild aplicado')
